[package]
name = "beta-example"
version = "1.4.1"
edition = "2024"

[dependencies]
svgr-macro.workspace = true
lazy_static = "1.4.0"
libm = "0.2.1"
rand = "0.8.5"
hello-world-example = { path = "../hello-world", default-features = false }
marketing-example = { path = "../marketing", default-features = false }
podcast-example = { path = "../podcast", default-features = false }
tiktok-example = { path = "../tiktok", default-features = false }
fframes.workspace = true

# `--renderer cpu|skia-cpu|gpu`: Skia on Metal on macOS, on Vulkan everywhere else
# `preview`: real-time GPU window
[target.'cfg(target_os = "macos")'.dependencies]
fframes_skia_renderer = { workspace = true, features = ["metal", "cli"] }
fframes_native_player = { workspace = true, features = ["metal", "audio"] }

[target.'cfg(not(any(target_os = "macos", target_arch = "wasm32")))'.dependencies]
fframes_skia_renderer = { workspace = true, features = ["vulkan", "cli"] }
fframes_native_player = { workspace = true, features = ["vulkan", "audio"] }

# FFmpeg codecs, portable so cached source builds work across CI runner CPUs. Windows
# links a prebuilt FFmpeg instead (see README).
[target.'cfg(not(any(target_arch = "wasm32", windows)))'.dependencies]
fframes = { workspace = true, features = ["h264", "libav-agree-gpl", "build-portable"] }

[features]
default = ["renderer"]
renderer = [
	"fframes/compile-time-svgtree",
	"fframes/cli",
	"hello-world-example/renderer",
	"marketing-example/renderer",
	"podcast-example/renderer",
	"tiktok-example/renderer",
]

[lib]
name = "beta_example"
path = "src/lib.rs"
doctest = false

[[bin]]
name = "beta_example_bin"
path = "src/main.rs"
required-features = ["renderer"]

[lints]
workspace = true

