 78	// ---------- motion ----------
 79	export const PopIn: React.FC<{at: number; seed?: string; children: React.ReactNode; origin?: string; style?: React.CSSProperties}> = ({at, seed = 'pop', children, origin = '50% 50%', style}) => {
 80	  const frame = useCurrentFrame();
 81	  const {fps} = useVideoConfig();
 82	  const s = spring({frame: frame - at, fps, config: {damping: 12, stiffness: 180, mass: 0.6}});
 83	  const tilt = (random(seed) - 0.5) * 8;
 84	  return (
 85	    <div style={{position: 'absolute', inset: 0, transformOrigin: origin, scale: String(s), rotate: `${tilt * (1 - s)}deg`, opacity: frame < at ? 0 : 1, ...style}}>
 86	      {children}
 87	    </div>
 88	  );
 89	};
