 91	export const SlideIn: React.FC<{at: number; dx?: number; dy?: number; dur?: number; children: React.ReactNode}> = ({at, dx = 0, dy = 0, dur = 10, children}) => {
 92	  const frame = useCurrentFrame();
 93	  const u = interpolate(frame, [at, at + dur], [1, 0], {...clamp, easing: Easing.bezier(0.16, 1.25, 0.3, 1)});
 94	  return <div style={{position: 'absolute', inset: 0, translate: `${dx * u}px ${dy * u}px`, opacity: frame < at ? 0 : 1}}>{children}</div>;
 95	};
