 98	export const Boil: React.FC<{amp?: number; rot?: number; seed?: string; children: React.ReactNode}> = ({amp = 1.5, rot = 0.2, seed = 'boil', children}) => {
 99	  const step = Math.floor(useCurrentFrame() / 2);
100	  return (
101	    <div style={{position: 'absolute', inset: 0, translate: `${(random(`${seed}x${step}`) - 0.5) * 2 * amp}px ${(random(`${seed}y${step}`) - 0.5) * 2 * amp}px`, rotate: `${(random(`${seed}r${step}`) - 0.5) * 2 * rot}deg`}}>
102	      {children}
103	    </div>
104	  );
105	};
