107	// Scene camera: smooth push toward a focal point, plus an optional accent push at `accent`.
108	export const CameraPush: React.FC<{dur: number; to?: number; origin?: string; drift?: [number, number]; accent?: number; children: React.ReactNode}> = ({dur, to = 1.07, origin = '50% 45%', drift = [0, 0], accent, children}) => {
109	  const f = useCurrentFrame();
110	  const base = interpolate(f, [0, dur], [1, to], {...clamp, easing: Easing.inOut(Easing.quad)});
111	  const acc = accent === undefined ? 0 : interpolate(f, [accent, accent + 30], [0, 0.1], {...clamp, easing: Easing.bezier(0.2, 0.9, 0.3, 1)});
112	  const p = interpolate(f, [0, dur], [0, 1], clamp);
113	  return (
114	    <AbsoluteFill style={{transformOrigin: origin, scale: String(base + acc), translate: `${drift[0] * p}px ${drift[1] * p}px`}}>
115	      {children}
116	    </AbsoluteFill>
117	  );
118	};
