205	export const GrainOverlay: React.FC = () => {
206	  const f = useCurrentFrame();
207	  return (
208	    <AbsoluteFill style={{pointerEvents: 'none', opacity: 0.07, mixBlendMode: 'multiply'}}>
209	      <Img src={GRAIN} style={{width: '140%', height: '140%', objectFit: 'cover', translate: `${(random(`g${Math.floor(f / 2)}`) - 0.5) * 60}px ${(random(`h${Math.floor(f / 2)}`) - 0.5) * 60}px`}} />
210	    </AbsoluteFill>
211	  );
212	};
213	
214	// Idle helpers
215	export const bob = (f: number, period = 36, amp = 3, phase = 0) => Math.sin(((f + phase) / period) * Math.PI * 2) * amp;
216	export const hop = (f: number, at: number, dur = 12, h = 14) => { const u = (f - at) / dur; return u > 0 && u < 1 ? Math.sin(u * Math.PI) * h : 0; };
217	export const reach = (f: number, at: number, back?: number) => {
218	  const out = interpolate(f, [at, at + 6], [0, 1], {...clamp, easing: Easing.out(Easing.back(1.6))});
219	  return back === undefined ? out : out * interpolate(f, [back, back + 5], [1, 0], clamp);
220	};

  1	// The one base creature for the whole cast: a boxy paper critter with eyes only and stubby limbs.
  2	// Cast members differ by colour, accessory and name pill. (x, y) is the ground point under the body.
  3	import React from 'react';
  4	import {useCurrentFrame} from 'remotion';
  5	import {C} from '../tokens';
  6	import {Disc, Paper, Pill, Slab, bob} from '../paper/kit';
  7	
  8	export type Expr = 'idle' | 'sleep' | 'shock' | 'happy' | 'worried' | 'blink' | 'squint';
  9	export type Acc = 'none' | 'postCap' | 'monocle' | 'headphones' | 'visor' | 'cap' | 'hardhat' | 'beret' | 'glasses' | 'headset' | 'bowtie';
 10	// Hat-like accessories push the name pill up.
 11	const HAT: Acc[] = ['postCap', 'headphones', 'cap', 'hardhat', 'beret'];
 12	
 13	export const Critter: React.FC<{
 14	  x: number; y: number; size?: number; color?: string; shade?: string;
 15	  expr?: Expr; acc?: Acc; tag?: string; tagColor?: string;
 16	  armR?: number; armRAngle?: number; armL?: number; armLAngle?: number;   // reach 0–1, angle deg (negative = up)
 17	  lean?: number; lift?: number; face?: 1 | -1; tape?: boolean; phase?: number; idle?: boolean;
 18	  holdR?: React.ReactNode;   // drawn at the tip of the right arm
 19	  accColor?: string; accShade?: string;   // colour for cap / hardhat / beret / headset / bowtie (role colour for agents)
 20	}> = ({x, y, size = 240, color = C.hero, shade = C.heroLo, expr = 'idle', acc = 'none', tag, tagColor = C.purple, accColor, accShade, armR = 0, armRAngle = 0, armL = 0, armLAngle = 0, lean = 0, lift = 0, face = 1, tape, phase = 0, idle = true, holdR}) => {
 21	  const f = useCurrentFrame();
 22	  const u = size / 10;
 23	  const b = idle ? bob(f, 36, 3, phase) : 0;
 24	  const bLag = idle ? bob(f - 2, 36, 3, phase) : 0;
 25	  const blink = expr === 'idle' && (f + Math.round(phase * 7)) % 83 < 3;
 26	  const bodyW = 10 * u, bodyH = 7 * u, legH = 2.2 * u;
 27	  const top = -legH - bodyH;   // body top, relative to ground
 28	  const e = expr === 'blink' || blink ? 'blink' : expr;
 29	  const eyeW = u * (e === 'shock' ? 1.3 : 1), eyeH = u * (e === 'shock' ? 2.1 : 1.6);
 30	  const eyes = [[3 * u, 2 * u], [6 * u, 2 * u]];
 31	  const arm = (side: 1 | -1, reach: number, ang: number) => {
 32	    const len = 2.3 * u + reach * 5 * u;
 33	    const ax = side === 1 ? bodyW - 0.4 * u : 0.4 * u;
 34	    return (
 35	      <div style={{position: 'absolute', left: ax, top: 3.4 * u, width: 0, height: 0, rotate: `${side === 1 ? ang : -ang}deg`}}>
 36	        <Slab x={side === 1 ? 0 : -len} y={-0.7 * u} w={len} h={1.4 * u} color={color} shade={shade} shadeH={0.3} r={3} />
 37	        {side === 1 && holdR ? <div style={{position: 'absolute', left: len, top: 0}}>{holdR}</div> : null}
 38	      </div>
 39	    );
 40	  };
 41	  return (
 42	    <div style={{position: 'absolute', left: x, top: y, width: 0, height: 0, scale: `${face} 1`}}>
 43	      <div style={{position: 'absolute', left: 0, top: -lift + b, width: 0, height: 0, rotate: `${lean}deg`, transformOrigin: '0 0'}}>
 44	        <div style={{position: 'absolute', left: -bodyW / 2, top: top, width: bodyW, height: bodyH + legH}}>
 45	          <Paper lift={5}>
 46	            {/* legs: four stubs */}
 47	            {[1.2, 3.3, 5.7, 7.8].map((lx, i) => (
 48	              <Slab key={i} x={lx * u} y={bodyH - 0.3 * u} w={1 * u} h={legH + 0.3 * u} color={color} shade={shade} shadeH={0.35} r={2} />
 49	            ))}
 50	            {arm(-1, armL, armLAngle)}
 51	            <Slab x={0} y={0} w={bodyW} h={bodyH} color={color} shade={shade} shadeH={0.16} r={4} />
 52	            {arm(1, armR, armRAngle)}
 53	            {/* eyes */}
 54	            {eyes.map(([ex, ey], i) =>
 55	              e === 'sleep' || e === 'blink' || e === 'happy' ? (
 56	                <div key={i} style={{position: 'absolute', left: ex - 0.15 * u, top: ey + (e === 'happy' ? 0.3 * u : 0.8 * u), width: 1.3 * u, height: 0.28 * u, background: C.ink, borderRadius: e === 'happy' ? '50% 50% 0 0' : 2}} />
 57	              ) : (
 58	                <div key={i} style={{position: 'absolute', left: ex + (e === 'worried' ? (i ? -0.2 : 0.2) * u : 0) + (1 * u - eyeW) / 2, top: ey + (e === 'squint' ? 0.5 * u : 0), width: eyeW, height: e === 'squint' ? 0.6 * u : eyeH, background: C.ink, borderRadius: 2}} />
 59	              ),
 60	            )}
 61	            {e === 'shock' ? <div style={{position: 'absolute', left: 4.4 * u, top: 4.5 * u, width: 1.1 * u, height: 1.1 * u, borderRadius: '50%', background: C.ink}} /> : null}
 62	            {e === 'happy' ? <div style={{position: 'absolute', left: 4 * u, top: 4.4 * u, width: 2 * u, height: 0.3 * u, background: C.ink, borderRadius: 3}} /> : null}
 63	            {tape ? <Slab x={2.6 * u} y={4.1 * u} w={4.8 * u} h={1.3 * u} color={C.tape} rot={-6} r={2} style={{opacity: 0.92}} /> : null}
 64	            {/* accessories */}
 65	            {acc === 'postCap' ? (
 66	              <>
 67	                <Slab x={1.2 * u} y={-1.9 * u} w={7.6 * u} h={2.1 * u} color={C.cap} shade={C.capLo} shadeH={0.3} r="40% 40% 6px 6px" />
 68	                <Slab x={5.4 * u} y={-0.1 * u} w={4.6 * u} h={0.7 * u} color={C.capLo} r={3} />
 69	                <Slab x={4.3 * u} y={-1.5 * u} w={1.3 * u} h={1.1 * u} color={C.brass} shade={C.brassLo} r={3} />
 70	              </>
 71	            ) : null}
 72	            {acc === 'monocle' ? (
 73	              <>
 74	                <div style={{position: 'absolute', left: 5.5 * u, top: 1.5 * u, width: 2 * u, height: 2 * u, borderRadius: '50%', border: `${0.35 * u}px solid ${C.brass}`, boxSizing: 'border-box', background: 'rgba(255,255,255,0.12)'}} />
 75	                <div style={{position: 'absolute', left: 6.4 * u, top: 3.5 * u, width: 0.2 * u, height: 2.4 * u, background: C.brassLo, rotate: '-12deg'}} />
 76	                <Slab x={3.4 * u} y={6.3 * u} w={3.2 * u} h={1.3 * u} color={C.nogo} shade={C.nogoDim} r="40%" />
 77	              </>
 78	            ) : null}
 79	            {acc === 'headphones' ? (
 80	              <>
 81	                <div style={{position: 'absolute', left: 0.6 * u, top: -1.6 * u, width: 8.8 * u, height: 4 * u, borderRadius: '50% 50% 0 0', border: `${0.6 * u}px solid ${C.board}`, borderBottom: 'none', boxSizing: 'border-box'}} />
 82	                <Slab x={-0.4 * u} y={1.4 * u} w={1.5 * u} h={2.4 * u} color={C.board} r={6} />
 83	                <Slab x={8.9 * u} y={1.4 * u} w={1.5 * u} h={2.4 * u} color={C.board} r={6} />
 84	              </>
 85	            ) : null}
 86	            {acc === 'visor' ? <Slab x={0.8 * u} y={-0.8 * u} w={9.6 * u} h={1.2 * u} color={accColor ?? C.go} shade={accShade ?? C.goDim} shadeH={0.4} r={4} /> : null}
 87	            {acc === 'cap' ? (
 88	              // "you": blue baseball cap, brim forward (to the right)
 89	              <>
 90	                <Slab x={1.4 * u} y={-2.1 * u} w={7.2 * u} h={2.4 * u} color={accColor ?? C.cap} shade={accShade ?? C.capLo} shadeH={0.28} r="50% 50% 4px 4px" />
 91	                <Slab x={6.2 * u} y={0} w={4.4 * u} h={0.75 * u} color={accShade ?? C.capLo} r="3px 40% 40% 3px" />
 92	                <Disc x={5 * u} y={-2 * u} d={0.9 * u} color={accShade ?? C.capLo} />
 93	              </>
 94	            ) : null}
 95	            {acc === 'hardhat' ? (
 96	              <>
 97	                <Slab x={1 * u} y={-2.3 * u} w={8 * u} h={2.6 * u} color={accColor ?? C.amber} shade={accShade ?? C.amberDim} shadeH={0.22} r="50% 50% 3px 3px" />
 98	                <Slab x={0.2 * u} y={0} w={9.6 * u} h={0.7 * u} color={accShade ?? C.amberDim} r={3} />
 99	                <Slab x={4.6 * u} y={-2.2 * u} w={0.8 * u} h={2.2 * u} color={accShade ?? C.amberDim} r={2} />
100	              </>
101	            ) : null}
102	            {acc === 'beret' ? (
103	              <>
104	                <Slab x={1.6 * u} y={-1.5 * u} w={7.6 * u} h={1.9 * u} color={accColor ?? C.ink} shade={accShade ?? '#000'} shadeH={0.3} r="55% 45% 40% 40%" rot={-6} />
105	                <Slab x={4.8 * u} y={-2.1 * u} w={0.6 * u} h={0.9 * u} color={accColor ?? C.ink} r={3} />
106	              </>
107	            ) : null}
108	            {acc === 'glasses' ? (
109	              <>
110	                {[[2.4, 1.6], [5.6, 1.6]].map(([gx, gy], i) => (
111	                  <div key={i} style={{position: 'absolute', left: gx * u, top: gy * u, width: 2.1 * u, height: 2.1 * u, borderRadius: '50%', border: `${0.32 * u}px solid ${C.ink}`, boxSizing: 'border-box', background: 'rgba(255,255,255,0.14)'}} />
112	                ))}
113	                <div style={{position: 'absolute', left: 4.4 * u, top: 2.5 * u, width: 1.3 * u, height: 0.3 * u, background: C.ink}} />
114	              </>
115	            ) : null}
116	            {acc === 'headset' ? (
117	              <>
118	                <div style={{position: 'absolute', left: 0.4 * u, top: -1.2 * u, width: 9.2 * u, height: 3.4 * u, borderRadius: '50% 50% 0 0', border: `${0.45 * u}px solid ${C.board}`, borderBottom: 'none', boxSizing: 'border-box'}} />
119	                <Slab x={-0.3 * u} y={1.6 * u} w={1.3 * u} h={2 * u} color={accColor ?? C.board} r={6} />
120	                <div style={{position: 'absolute', left: 0.3 * u, top: 3.4 * u, width: 3.2 * u, height: 0.3 * u, background: C.board, rotate: '18deg', transformOrigin: '0 0'}} />
121	                <Disc x={3.5 * u} y={4.5 * u} d={0.8 * u} color={C.board} />
122	              </>
123	            ) : null}
124	            {acc === 'bowtie' ? (
125	              <>
126	                <Slab x={3.5 * u} y={6 * u} w={1.5 * u} h={1.4 * u} color={accColor ?? C.nogo} r="40% 10% 10% 40%" />
127	                <Slab x={5 * u} y={6 * u} w={1.5 * u} h={1.4 * u} color={accColor ?? C.nogo} r="10% 40% 40% 10%" />
128	                <Disc x={5 * u} y={6.7 * u} d={0.8 * u} color={accShade ?? C.nogoDim} />
129	              </>
130	            ) : null}
131	          </Paper>
132	        </div>
133	        {tag ? (
134	          <div style={{position: 'absolute', left: 0, top: top - (HAT.includes(acc) ? 3.3 : 1.6) * u + (bLag - b), scale: `${face} 1`}}>
135	            <Pill x={0} y={0} text={tag} bg={tagColor} size={Math.max(24, 0.13 * size)} />
136	          </div>
137	        ) : null}
138	      </div>
139	    </div>
140	  );
141	};

