[package]
name = "motion-papercut"
version = "0.1.0"
edition = "2021"
description = "Papercut style engine for the motion-explainer skills: builds an explainer reel from episode.json + plan.json with fframes."
license = "MIT"

[dependencies]
fframes = { version = "1.4.2-rc.1", default-features = false, features = ["cli", "captions"] }
clap = { version = "4.5", features = ["derive"] }

[features]
default = ["renderer"]
# the encoder + the CLI (render, frame, strip, inspect, audio). The library itself builds without it.
renderer = ["fframes/compile-time-svgtree", "fframes/cpu_renderer"]
# encode H.264 through the bundled portable ffmpeg; leave off on machines without a toolchain for it
encode = ["fframes/h264", "fframes/build-portable"]

[lints.rust]
unexpected_cfgs = "allow"

[profile.release]
opt-level = 3
lto = "thin"
codegen-units = 1
=== lib.rs ===
//! Papercut style engine for the motion-explainer skills, on top of fframes.
//!
//! The episode project holds `episode.json` (beats, banners, cuts, hook, audio, style, engine),
//! `src/plan.json` (frames and word cues, written by `core/tools/build_vo.py`) and `src/scenes/<Id>.rs`
//! (one module per scene, generated from the plan by [`gen`]). This crate is the engine the project
//! builds against:
//!
//! - [`tokens`]   palette, fonts, room colours, timings
//! - [`kit`]      paper primitives: rough/torn filters, grain, Slab, Disc, Pill, Card, PopIn, Boil, cameras
//! - [`camera`]   the kit's camera moves (orbit, snap zoom, crane, crab, dolly, rack focus, ...)
//! - [`cut`]      the scene transitions (whip, page turn, tear away, tape pull, ...) and the cut series
//! - [`cast`]     the boxy paper critter and its accessories
//! - [`props`]    the prop bank (everyday, gpu, leak, stage, usage, council, crowd, aura, cable)
//! - [`ui`]       paper UI: monitor, laptop, app window, terminal, repo card, button, counter
//! - [`sets`]     rooms, backdrops and set dressing
//! - [`overlay`]  the taped banner, the torn word-tag captions, the hook title, grain
//! - [`look`]     film weave, felt fibre, lamp flicker, halftone, graph paper, proof marks
//! - [`video`]    reads episode.json / plan.json and builds the fframes Video + AudioMap
//!
//! Scene modules import this crate (`use motion_papercut::*;`) and get the helpers without a
//! per-episode copy of the kit.

pub mod anim;
pub mod camera;
pub mod cast;
pub mod cut;
pub mod gen;
pub mod hook;
pub mod kit;
pub mod look;
pub mod overlay;
pub mod props;
pub mod sets;
pub mod tokens;
pub mod ui;
pub mod video;

pub use anim::{bob, hop, reach, Animation, Random};
pub use cast::{Acc, Critter, CritterOpts, Expr};
pub use camera::*;
pub use cut::{CutKind, CutSeries, CutSpec};
pub use hook::{HookTitle, TornTag};
pub use kit::*;
pub use look::*;
pub use sets::*;
pub use tokens::{palette as C, rooms, FONT, H, T, W};
pub use video::{Episode, Plan, PlanScene, PlanWord};

/// Re-exported so a scene module never depends on fframes directly.
pub use fframes;
pub use fframes::{svgr, svgr_macro};
pub use fframes::{AudioMap, AudioTimestamp, FFramesContext, Frame, Overlap, Scene, SceneInfo, Scenes, Svgr, Video};

/// Everything a scene can reach at render time: the scene's own slice of the plan plus the episode.
pub struct Ctx<'a> {
    pub ep: &'a Episode,
    pub plan: &'a Plan,
    pub scene: &'a PlanScene,
}

impl Ctx<'_> {
    /// Frame of the first time `word` (or a word starting with it) is said in this scene; `n` counts repeats.
    pub fn cue(&self, word: &str, n: usize) -> usize {
        let want = norm(word);
        let mut k = 0;
        for w in &self.scene.words {
            if norm(&w.text).starts_with(&want) {
                if k == n {
                    return w.f;
                }
                k += 1;
            }
        }
        panic!("cue \"{word}\"#{n} not in {}", self.scene.id);
    }

    pub fn dur(&self) -> usize {
        self.scene.duration_in_frames
    }
}

pub fn norm(w: &str) -> String {
    w.to_lowercase().chars().filter(|c| c.is_ascii_alphanumeric()).collect()
}
