//! Test-only helpers. Kept in `src` rather than a `tests/` module because the lifetime types make
//! a standalone integration test awkward, and because only the unit tests need them.

use fframes::Svgr;

/// The SVG markup a [`Svgr`] rasterises to.
///
/// [`Svgr`]'s `Display` prints the *tree's debug form* under `compile-time-svgtree`, not markup,
/// so tests that want to check "is this element present, with this attribute" have to go through
/// the same conversion the renderer uses.
#[must_use]
pub fn markup(v: Svgr<'_>) -> String {
    use fframes::usvgr::fontdb::Database;

    let mut cache = fframes::usvgr::Cache::new_with_text_cache(64);
    let db = Database::new();
    let tree = v
        .into_svg_tree(&fframes::usvgr::Options::default(), &mut cache, &db)
        .expect("the kit only builds well-formed SVG");
    tree.to_string(&fframes::usvgr::WriteOptions::default())
}

/// True when the markup contains no drawing element at all, for "this layer is off" assertions.
#[must_use]
pub fn is_blank(v: Svgr<'_>) -> bool {
    let out = markup(v);
    !["<rect", "<g", "<text", "<path", "<circle", "<image", "<line", "<ellipse"]
        .iter()
        .any(|tag| out.contains(tag))
}

