    match v.into_svg_tree(&fframes::usvgr::Options::default(), &mut cache, &db) {
        Ok(t) => t.to_string(&fframes::usvgr::WriteOptions::default()),
        Err(e) => format!("ERR {e:?}"),
    }
}

#[test]
fn dbg_nest() {
    // A whole svg written in one literal, with the child inline.
    let a = fframes::svgr!(<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920"><rect x="1" y="2" width="10" height="10" fill="#f00" /></svg>);
    println!("INLINE: {}", conv(a));
    // Same, but composed from a variable.
    let leaf = fframes::svgr!(<rect x="1" y="2" width="10" height="10" fill="#f00" />);
    let b = fframes::svgr!(<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920">{leaf}</svg>);
    println!("VAR: {}", conv(b));
}
#[test]
fn dbg_nest() {
    use crate::*;
    let inner = fframes::svgr!(<text x="5" y="5" fill="#F5C542">{"HI"}</text>);
