#[derive(Debug, PartialEq, Clone)]
#[allow(missing_docs)]
/// FFrames change: NestedNodeKind used to construct trees in macro
pub enum NestedNodeKind<'a> {
    Root,
    Element { tag_name: EId },
    Text(roxmltree::StringStorage<'a>),
}

#[cfg(feature = "proc-macro")]
impl quote::ToTokens for NestedNodeKind<'_> {
    fn to_tokens(&self, tokens: &mut proc_macro2::TokenStream) {
        match self {
            NestedNodeKind::Root => quote! { NestedNodeKind::Root },
            NestedNodeKind::Element { tag_name } => {
                let tag_name = tag_name.to_tokens();
                quote! {
                    NestedNodeKind::Element {
                        tag_name: #tag_name,
                    }
                }
            }
            // the trick here: when we convert totokens we never need to own the string
            NestedNodeKind::Text(roxmltree::StringStorage::Owned(value)) => {
                use std::ops::Deref;
                let value = value.deref();
                quote! { NestedNodeKind::Text(roxmltree::StringStorage::Borrowed(#value)) }
            }
            NestedNodeKind::Text(roxmltree::StringStorage::Borrowed(value)) => {
                quote! { NestedNodeKind::Text(roxmltree::StringStorage::Borrowed(#value)) }
            }
        }
        .to_tokens(tokens)
    }
}

#[derive(Debug, PartialEq, Clone)]
#[allow(missing_docs)]
/// FFrames change: NestedNodeDataused to construct trees in macro
pub struct NestedNodeData<'input> {
    pub kind: NestedNodeKind<'input>,
    pub attrs: Box<[Attribute<'input>]>,
    pub children: Vec<Option<NestedNodeData<'input>>>,
    /// Pre-computed hash for cache optimization.
    /// If Some, the cache can use this directly instead of computing at runtime.
    /// This is set at compile-time by svgr-macro for fully static nodes.
    pub static_hash: Option<u64>,
}

/// Path geometry (`d` or `points`) known at compile time.
///
/// The `svgr!` macro places it in a `static`, so the geometry is converted into a
/// `tiny_skia_path::Path` once per process instead of once per rendered frame.
pub struct StaticPathData {
    segments: &'static [svgrtypes::PathSegment],
    path: std::sync::OnceLock<Option<Arc<tiny_skia_path::Path>>>,
}

impl StaticPathData {
    /// `segments` must already describe the final geometry, e.g. `polygon` points end
    /// with a `ClosePath`.
    pub const fn new(segments: &'static [svgrtypes::PathSegment]) -> Self {
        Self {
            segments,
            path: std::sync::OnceLock::new(),
        }
    }

    pub fn segments(&self) -> &'static [svgrtypes::PathSegment] {
        self.segments
    }

    pub(crate) fn path(&self) -> Option<Arc<tiny_skia_path::Path>> {
        self.path
            .get_or_init(|| super::shapes::convert_path_from_segments(self.segments))
            .clone()
    }
}

impl PartialEq for StaticPathData {
    fn eq(&self, other: &Self) -> bool {
        std::ptr::eq(self, other) || self.segments == other.segments
    }
}

impl std::fmt::Debug for StaticPathData {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "StaticPathData({} segments)", self.segments.len())
    }
}

