//! Serialise a [`Svgr`] to standalone SVG markup.
//!
//! The kit's `svgr!` trees are *fragments*: they carry dangling paint-server
//! references (`url(#pc-torn)`, `url(#pc-grain-…)`) and text without a resolved
//! font. `usvgr` drops anything it cannot resolve, so a fragment converted on
//! its own comes back empty.
//!
//! Playwright can't resolve those references either — `element.screenshot()`
//! only paints what the document can actually draw. So instead of converting,
//! this walks the compiled tree straight back to SVG text, keeping every
//! attribute verbatim and splicing `<defs>` into the root once. The result is
//! the same markup the Remotion kit emits, which is what we want to test.

use fframes::Svgr;
use fframes::usvgr::svgtree::{NestedNodeData, NestedNodeKind, SvgAttributeValue};

const NS: &str = "http://www.w3.org/2000/svg";

/// Serialise `v` inside a `W`×`H` root carrying the kit `<defs>`.
pub fn markup(v: Svgr<'_>) -> String {
    let (w, h) = (crate::tokens::W, crate::tokens::H);
    let mut out = String::with_capacity(4096);
    out.push_str(&format!(
        r#"<svg xmlns="{NS}" width="{w}" height="{h}" viewBox="0 0 {w} {h}">"#
    ));
    for node in &crate::kit::defs().svg_tree.nodes {
        write_node(node.as_ref(), &mut out);
    }
    for node in &crate::sets::room_defs().svg_tree.nodes {
        write_node(node.as_ref(), &mut out);
    }
    for node in &v.svg_tree.nodes {
        write_node(node.as_ref(), &mut out);
    }
    out.push_str("</svg>");
    out
}

/// True when `v` draws nothing a viewer could see.
pub fn is_blank(v: Svgr<'_>) -> bool {
    !v.svg_tree
        .nodes
        .iter()
        .flatten()
        .any(|n| match &n.kind {
            NestedNodeKind::Element { tag_name } => {
                !matches!(tag_name.to_str(), "defs" | "title" | "desc" | "metadata")
            }
            NestedNodeKind::Text(t) => !text_of(t).trim().is_empty(),
            NestedNodeKind::Root => false,
        })
}

fn text_of<'a>(t: &'a fframes::usvgr::roxmltree::StringStorage<'a>) -> &'a str {
    match t {
        fframes::usvgr::roxmltree::StringStorage::Borrowed(s) => s,
        fframes::usvgr::roxmltree::StringStorage::Owned(s) => s,
    }
}

fn write_node(node: Option<&NestedNodeData<'_>>, out: &mut String) {
    let Some(node) = node else { return };
    match &node.kind {
        NestedNodeKind::Root => {}
        NestedNodeKind::Text(t) => escape_into(text_of(t), out),
        NestedNodeKind::Element { tag_name } => {
            let tag = tag_name.to_str();
            out.push('<');
            out.push_str(tag);
            for attr in node.attrs.iter() {
                let Some(value) = attr_value(&attr.value) else {
                    continue;
                };
                out.push(' ');
                out.push_str(attr.name.to_str());
                out.push_str("=\"");
                escape_into(&value, out);
                out.push('"');
            }
            // `<image>` without an href paints nothing; keep the document honest.
            if node.children.iter().flatten().next().is_none() {
                out.push_str("/>");
            } else {
                out.push('>');
                for child in &node.children {
                    write_node(child.as_ref(), out);
                }
                out.push_str("</");
                out.push_str(tag);
                out.push('>');
            }
        }
    }
}

fn attr_value(v: &SvgAttributeValue<'_>) -> Option<String> {
    use fframes::usvgr::roxmltree::StringStorage;
    use fframes::usvgr::svgtree::SvgAttributeValue as V;
    Some(match v {
        V::StringStorage(StringStorage::Borrowed(s)) => (*s).to_string(),
        V::StringStorage(StringStorage::Owned(s)) => s.to_string(),
        V::Float(f, StringStorage::Borrowed(s)) | V::Float(f, StringStorage::Owned(_) if false) => {
            if s.is_empty() {
                fmt_float(*f)
            } else {
                (*s).to_string()
            }
        }
        V::Float(f, _) => fmt_float(*f),
        V::Length(l) => l.to_string(),
        V::Transform(t) => t.to_string(),
        V::Color(c) => c.to_string(),
        V::PathData(d) => d
            .iter()
            .map(|seg| seg.to_string())
            .collect::<Vec<_>>()
            .join(" "),
        _ => return None,
    })
}

fn fmt_float(f: f32) -> String {
    if f.fract() == 0.0 && f.abs() < 1e7 {
        format!("{}", f as i64)
    } else {
        format!("{f}")
    }
}

fn escape_into(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
}

