use fframes::Svgr;

/// Serialise a kit fragment to standalone SVG markup.
///
/// A fragment on its own is not convertible: it references paint servers
/// (`url(#pc-torn)`, `url(#pc-grain-…)`) and font families that only exist once
/// the kit `<defs>` are mounted and `media/fonts` is loaded. `usvgr` silently
/// drops anything it cannot resolve, so the wrapper below mounts both before
/// converting — the same document the renderer assembles for a real frame.
pub fn markup(v: Svgr<'_>) -> String {
    let (w, h) = (crate::tokens::W, crate::tokens::H);
    let doc = fframes::svgr!(<svg xmlns="http://www.w3.org/2000/svg" width={w} height={h} viewBox={format!("0 0 {w} {h}")}>
        {crate::kit::defs()}
        {crate::sets::room_defs()}
        {crate::kit::default_grain_patterns("grain.png")}
        <g>{v}</g>
    </svg>);
    let mut cache = fframes::usvgr::Cache::new_with_text_cache(64);
    doc.into_svg_tree(&fframes::usvgr::Options::default(), &mut cache, fonts())
        .expect("the kit only builds well-formed SVG")
        .to_string(&fframes::usvgr::WriteOptions::default())
}

fn fonts() -> &'static fframes::usvgr::fontdb::Database {
    use std::sync::OnceLock;
    static DB: OnceLock<fframes::usvgr::fontdb::Database> = OnceLock::new();
    DB.get_or_init(|| {
        let mut db = fframes::usvgr::fontdb::Database::new();
        db.load_fonts_dir(concat!(env!("CARGO_MANIFEST_DIR"), "/media/fonts"));
        db
    })
}

/// True when `v` would draw nothing a viewer could see.
pub fn is_blank(v: Svgr<'_>) -> bool {
    let out = markup(v);
    !["<rect", "<g", "<text", "<path", "<circle", "<image", "<line", "<ellipse"]
        .iter()
        .any(|tag| out.contains(tag))
}
EOF
