--- core/voice/build_timing.py
# Build timing.js: per-scene narration duration + word timestamps aligned to the script text.
# With ASR json (from voice/asr.py) words get real times; without it, a 2.75 wps estimate.
import json, sys, re, difflib, os
script = json.load(open("script.json"))
asr = json.load(open(sys.argv[1])) if len(sys.argv) > 1 else {}
CH = os.environ.get("CHOSEN", "voice/chosen.json")
chosen = json.load(open(CH)) if os.path.exists(CH) else {}
norm = lambda w: re.sub(r"[^a-z0-9]", "", w.lower())
seg = {}
for ln in script:
    words = ln["text"].split()
    path = chosen.get(ln["id"])
    a = asr.get(path) if path else None
    if a:
        aw = a["words"]; dur = a["dur"]
        sm = difflib.SequenceMatcher(a=[norm(w) for w in words], b=[norm(x["w"]) for x in aw], autojunk=False)
        times = [None] * len(words)
        for blk in sm.get_matching_blocks():
            for k in range(blk.size): times[blk.a + k] = (aw[blk.b + k]["s"], aw[blk.b + k]["e"])
        # interpolate gaps between matched neighbours
        for i in range(len(words)):
            if times[i] is None:
                j = i
                while j < len(words) and times[j] is None: j += 1
                lo = times[i - 1][1] if i else 0.0
                hi = times[j][0] if j < len(words) else dur
                n = j - i
                for k in range(n): times[i + k] = (lo + (hi - lo) * k / n, lo + (hi - lo) * (k + 1) / n)
    else:
        dur = len(words) / 2.75 + 0.2
        times = [(i / 2.75, (i + 1) / 2.75) for i in range(len(words))]
    seg[ln["id"]] = {"dur": round(dur, 3), "file": path, "words": [{"w": w, "s": round(t[0], 3), "e": round(t[1], 3)} for w, t in zip(words, times)]}
open(os.environ.get("TIMING_OUT", "timing.js"), "w").write("// generated by build_timing.py\nconst VO = " + json.dumps({"order": [l["id"] for l in script], "seg": seg}) + ";\n")
print({k: v["dur"] for k, v in seg.items()}, "total", round(sum(v["dur"] for v in seg.values()), 1))
--- core/voice/asr.py
# Transcribe wavs with whisper-large-v3-turbo; print text + word timestamps as JSON.
#   usage: python asr.py a.wav b.wav ... > asr.json     ({path: {"text", "words": [{"w", "s", "e"}], "dur"}}, seconds)
#   backends, first one that imports wins:
#     mlx-whisper     pip install mlx-whisper       (Apple Silicon; the one this pipeline was written against)
#     faster-whisper  pip install faster-whisper    (CUDA or CPU; env FASTER_WHISPER_MODEL overrides the model name, default
#                                                    large-v3-turbo; try small.en on a slow CPU). Written later, less tested.
#   Any other ASR that writes the same JSON works too: pick.py, split_take.py and build_timing.py only read that file.
import sys, json, wave, os

try:
    import mlx_whisper

    def transcribe(p):
        r = mlx_whisper.transcribe(p, path_or_hf_repo="mlx-community/whisper-large-v3-turbo", word_timestamps=True, language="en")
        words = [{"w": w["word"].strip(), "s": round(w["start"], 3), "e": round(w["end"], 3)} for seg in r["segments"] for w in seg.get("words", [])]
        return r["text"].strip(), words
except ImportError:
    try:
        from faster_whisper import WhisperModel
    except ImportError:
        sys.exit("asr.py needs mlx-whisper (Apple Silicon) or faster-whisper: pip install mlx-whisper  |  pip install faster-whisper")
    _model = None

    def transcribe(p):
        global _model
        if _model is None:
            try:
                import torch
                cuda = torch.cuda.is_available()
            except ImportError:
                cuda = False
            _model = WhisperModel(os.environ.get("FASTER_WHISPER_MODEL", "large-v3-turbo"), device="cuda" if cuda else "cpu",
                                  compute_type="float16" if cuda else "int8")
        segs, _ = _model.transcribe(p, word_timestamps=True, language="en")
        segs = list(segs)
        words = [{"w": w.word.strip(), "s": round(w.start, 3), "e": round(w.end, 3)} for seg in segs for w in (seg.words or [])]
        return " ".join(seg.text.strip() for seg in segs).strip(), words

out = {}
for p in sys.argv[1:]:
    text, words = transcribe(p)
    w_ = wave.open(p); out[p] = {"text": text, "words": words, "dur": w_.getnframes() / w_.getframerate()}
print(json.dumps(out))
